// @generated by rustomp-import (netlist → MNA elements) — do not edit
// 由 lowpass.design.json 生成。改动请改网表后重新生成。
// 未知量 = 节点数 + 电压源支路数（地不占未知量）。

use rustomp_dsp::{GND, Netlist};

/// 总下标数（`Netlist<N>` 的 N；包含排在最后的固定电位节点）
pub const N: usize = 3;

/// LU 真正要处理的未知量个数（固定节点排在它之后，行列全零）
pub const UNKNOWNS: usize = 2;

/// 实时路径的牛顿迭代次数（`* @rustomp newton=` 指定；默认 3）

/// 2 次不够：方波/快速边沿下会欠收敛 → 次谐波极限环（DEVLOG E50）。
pub const NEWTON_ITERS: usize = 3;

/// 无可调参数。
#[derive(Clone, Copy, PartialEq, Default)]
pub struct Params;

/// 节点编号（0 = 地；其余按名字排序，保证 diff 稳定）
pub mod node {
    /// `IN`
    pub const IN: usize = 2;
    /// `OUT`
    pub const OUT: usize = 1;
}

/// 输入端口节点（`process(x)` 用 `net.set_fixed(FIXED_IN, x)`）
pub const IN: usize = 2;
/// 输出节点
pub const OUT: usize = 1;
/// 输入端口在 `Netlist::fixed` 里的下标（电源轨排在它前面）
pub const FIXED_IN: usize = 0;

/// 按网表搭出电路（`fs` 是**内层**采样率，含过采样倍率）。
pub fn build(fs: f64, p: &Params) -> Netlist<N> {
    let mut net = Netlist::<N>::new();
    net.set_unknowns(UNKNOWNS);
    let _ = (fs, p);
    // C1 (100n F)
    net.capacitor(node::OUT, GND, 1e-7);
    // R1 (10k Ω) IN—OUT
    net.resistor(node::IN, node::OUT, 10000.0);
    net.fix_node(IN, 0.0); // 输入端口，值由 process() 每拍写入
    net
}

/// 生成的实时电路（直接实现 `rustomp_dsp::Circuit`）。
pub struct Ckt {
    net: Netlist<N>,
    params: Params,
    fs: f64,
    /// 削波活动量（0..1）：二极管最大正向电流 / ACTIVITY_I_REF
    activity: f32,
}

/// 活动指示的参考电流（`* @rustomp activity_i=` 可改；**只驱动 GUI 的 LED**）
pub const ACTIVITY_I_REF: f64 = 5e-5;

impl rustomp_dsp::Circuit for Ckt {
    type Params = Params;

    fn new(sample_rate: f64) -> Self {
        let params = Params::default();
        let mut net = build(sample_rate, &params);
        net.solve_dc();
        Self { net, params, fs: sample_rate, activity: 0.0 }
    }

    fn set_sample_rate(&mut self, sample_rate: f64) {
        if (sample_rate - self.fs).abs() > 1e-9 {
            *self = Self::new(sample_rate);
        }
    }

    fn set_params(&mut self, params: Params) {
        if params == self.params {
            return;
        }
        self.params = params;
    }

    fn reset(&mut self) {
        self.net.reset();
        self.net.solve_dc();
    }

    fn process(&mut self, x: f64) -> f64 {
        let dt = 1.0 / self.fs;
        self.net.set_fixed(FIXED_IN, x);
        let v = self.net.step_fixed(dt, NEWTON_ITERS);
        // 削波活动量：网表里**所有二极管**正向电流的最大值（反向的不算）
        let mut imax = 0.0f64;
        for e in &self.net.elems {
            if let rustomp_dsp::Element::Diode { model, a, k } = e {
                let va = if *a == rustomp_dsp::GND { 0.0 } else { v[*a] };
                let vk = if *k == rustomp_dsp::GND { 0.0 } else { v[*k] };
                imax = imax.max(model.current(va - vk));
            }
        }
        self.activity = (imax / ACTIVITY_I_REF).clamp(0.0, 1.0) as f32;
        v[OUT]
    }

    /// 削波活动量（0..1）→ 引擎做快起慢落包络 → GUI 的 LED
    fn activity(&self) -> f32 {
        self.activity
    }
}
